css:
.deps{display:grid; gap:10px}
.dep-rel{font-family:var(--mono); font-size:15px; padding:8px 10px; border:1px solid var(--rule); border-radius:8px; background:var(--panel)}
.dep-rel b{color:var(--c3)}
.stepper{display:flex; flex-wrap:wrap; gap:8px; align-items:center; font-family:var(--mono); font-size:13.5px}
.sub-mem{display:grid; grid-template-columns:auto 1fr; gap:4px 12px; font-family:var(--mono); font-size:14px}
.sub-mem .yes{color:var(--c3)} .sub-mem .no{color:var(--warn)}
.gridin th{font-family:var(--mono); font-size:12px; font-weight:400; color:var(--muted); padding-bottom:2px}
.gridin td{padding:2px 3px}
.sz-row{display:flex; flex-wrap:wrap; gap:10px 18px; align-items:center; font-family:var(--display); font-size:14px; color:var(--muted)}
.basis-list{display:flex; flex-wrap:wrap; gap:10px; align-items:center}
